macro_rules! deps {
    () => {
        CleanupKind!();
    };
}

macro_rules! cleanup_kinds {
    () => {
        deps!();
        # [doc = " MSVC requires unwinding code to be split to a tree of *funclets*, where each funclet can only"] # [doc = " branch to itself or to its parent. Luckily, the code we generates matches this pattern."] # [doc = " Recover that structure in an analyze pass."] pub (crate) fn cleanup_kinds (mir : & mir :: Body < '_ >) -> IndexVec < mir :: BasicBlock , CleanupKind > { fn discover_masters < 'tcx > (result : & mut IndexSlice < mir :: BasicBlock , CleanupKind > , mir : & mir :: Body < 'tcx > ,) { for (bb , data) in mir . basic_blocks . iter_enumerated () { match data . terminator () . kind { TerminatorKind :: Goto { .. } | TerminatorKind :: UnwindResume | TerminatorKind :: UnwindTerminate (_) | TerminatorKind :: Return | TerminatorKind :: TailCall { .. } | TerminatorKind :: CoroutineDrop | TerminatorKind :: Unreachable | TerminatorKind :: SwitchInt { .. } | TerminatorKind :: Yield { .. } | TerminatorKind :: FalseEdge { .. } | TerminatorKind :: FalseUnwind { .. } => { } TerminatorKind :: Call { unwind , .. } | TerminatorKind :: InlineAsm { unwind , .. } | TerminatorKind :: Assert { unwind , .. } | TerminatorKind :: Drop { unwind , .. } => { if let mir :: UnwindAction :: Cleanup (unwind) = unwind { debug ! ("cleanup_kinds: {:?}/{:?} registering {:?} as funclet" , bb , data , unwind) ; result [unwind] = CleanupKind :: Funclet ; } } } } } fn propagate < 'tcx > (result : & mut IndexSlice < mir :: BasicBlock , CleanupKind > , mir : & mir :: Body < 'tcx > ,) { let mut funclet_succs = IndexVec :: from_elem (None , & mir . basic_blocks) ; let mut set_successor = | funclet : mir :: BasicBlock , succ | match funclet_succs [funclet] { ref mut s @ None => { debug ! ("set_successor: updating successor of {:?} to {:?}" , funclet , succ) ; * s = Some (succ) ; } Some (s) => { if s != succ { span_bug ! (mir . span , "funclet {:?} has 2 parents - {:?} and {:?}" , funclet , s , succ) ; } } } ; for (bb , data) in traversal :: reverse_postorder (mir) { let funclet = match result [bb] { CleanupKind :: NotCleanup => continue , CleanupKind :: Funclet => bb , CleanupKind :: Internal { funclet } => funclet , } ; debug ! ("cleanup_kinds: {:?}/{:?}/{:?} propagating funclet {:?}" , bb , data , result [bb] , funclet) ; for succ in data . terminator () . successors () { let kind = result [succ] ; debug ! ("cleanup_kinds: propagating {:?} to {:?}/{:?}" , funclet , succ , kind) ; match kind { CleanupKind :: NotCleanup => { result [succ] = CleanupKind :: Internal { funclet } ; } CleanupKind :: Funclet => { if funclet != succ { set_successor (funclet , succ) ; } } CleanupKind :: Internal { funclet : succ_funclet } => { if funclet != succ_funclet { debug ! ("promoting {:?} to a funclet and updating {:?}" , succ , succ_funclet) ; result [succ] = CleanupKind :: Funclet ; set_successor (succ_funclet , succ) ; set_successor (funclet , succ) ; } } } } } } let mut result = IndexVec :: from_elem (CleanupKind :: NotCleanup , & mir . basic_blocks) ; discover_masters (& mut result , mir) ; propagate (& mut result , mir) ; debug ! ("cleanup_kinds: result={:?}" , result) ; result }
    };
}

cleanup_kinds!();